const request = require('request');

const options = {
  method: 'GET',
  url: 'https://api.procore.com/rest/v1.0/tax_codes',
  qs: {
    company_id: 'SOME_INTEGER_VALUE',
    page: 'SOME_INTEGER_VALUE',
    per_page: 'SOME_INTEGER_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/tax_codes?company_id=SOME_INTEGER_VALUE&page=SOME_INTEGER_VALUE&per_page=SOME_INTEGER_VALUE"),
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

const request = require('request');

const options = {
  method: 'POST',
  url: 'https://api.procore.com/rest/v1.0/tax_codes',
  qs: {company_id: 'SOME_INTEGER_VALUE'},
  headers: {'content-type': 'application/json'},
  body: {
    tax_code: {
      code: 'GST@10%',
      description: 'Goods and Services Tax',
      origin_data: '{ parent_ids: [1,2] }',
      origin_id: '1VT-33778-013',
      rate1: 10,
      archived: false,
      default_tax_code: false
    }
  },
  json: true
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Post,
    RequestUri = new Uri("https://api.procore.com/rest/v1.0/tax_codes?company_id=SOME_INTEGER_VALUE"),
    Content = new StringContent("{\"tax_code\":{\"code\":\"GST@10%\",\"description\":\"Goods and Services Tax\",\"origin_data\":\"{ parent_ids: [1,2] }\",\"origin_id\":\"1VT-33778-013\",\"rate1\":10,\"archived\":false,\"default_tax_code\":false}}")
    {
        Headers =
        {
            ContentType = new MediaTypeHeaderValue("application/json")
        }
    }
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}

